    if (numeros.length !== 5) {
        console.error("El array debe contener exactamente 5 números.");
        return;
    }

    let hayPrimo = false;
    numeros.forEach(num => {
        if (esPrimo(num)) {
            console.log(num);
            hayPrimo = true;
        }
    });

    if (!hayPrimo) {
        console.log("No hay números primos en el array.");
    }
}

// Ejemplo de uso:
