First, let's define some basic operations that can be performed on a deque:

- Append an element to the front of the deque: `append_front(x)`
- Append an element to the back of the deque: `append_back(x)`

Using two stacks - one to represent the front of the deque and the other to represent the back of the deque - we can perform these operations when the deque is constructed from an existing collection of elements (assuming the elements are inserted in the correct order for the intended operation).

Here's an implementation using two stacks:

```python
class DoubleEndedQueue:
    def __init__(self, elements=None):
        self.front_stack = []
        self.back_stack = None
        if elements is not None:
            if isinstance(elements, list):
                self._build_back_stack(elements)
            elif elements == None:
                pass  # valid input, no action needed

        # Append new elements to the back of the existing deque
        for x in elements:
            self.append_back(self._build_back_stack(x))

        def _build_back_stack(sequence):
            # create and fill the back stack with elements
            self.back_stack = list(sequence[::-1])

    def append_front(self, x):
        """Add an element to the front of the deque."""
        if self.front_stack is None:
            self.front_stack = [x]
        else:
            self.front_stack.append(x)

    def append_back(self, x):
        """Add an element to the back of the deque."""
        if self.back_stack is None:
            self._build_back_stack(x)
        elif self.should_reverse_back_stack():
            self.back_stack.append(x)

    @property
    def should_reverse_back_stack(self):
        """Helper method to check if the back stack should be reversed"""
        return hasattr(self, "back_stack")

    def pop_front(self):
        """Remove and return the element from the front of the deque."""
        if self.front_stack:
            output = self.front_stack.pop()

        return output

    def pop_back(self):
        """Remove and return the element from the back of the deque."""
        if self.should_reverse_back_stack:
            self.back_stack = self.back_stack[:-1]  # remove the last element
            return self.back_stack.pop()

    def __len__(self):
        """Return the total number of elements in the deque."""
        front_stack_len = len(self.front_stack)
        if self.back_stack is not None:
            return front_stack_len + len(self.back_stack)
        return front_stack_len  # if back_stack is None, return length of front_stack only

