        # if the operation is performed on an existing deque).
        # We need to convert this to the appropriate length in the front stack.

        # Indexing support for the front of the deque
        if index < len(self):
            return self.front_stack[index]

    def __iter__(self):
        """Allow iteration to get the elements in the deque from front to back."""
        if self.back_stack is not None:
            self.back_stack += self.front_stack[::-1]
            return iter(self.back_stack)

        return iter(self.front_stack)

class DequeIterator:
